<template>
  <div class="app-container transaction-page">
    <div class="heading"><div><el-badge :value="pendingCount" :hidden="!pendingCount" :max="99"><h2>交易管理</h2></el-badge><p>家长个人账户 · 孩子课包、付款与交易</p></div><el-button type="primary" icon="el-icon-plus" :disabled="submitting" @click="openCreate">添加孩子信息</el-button></div>
    <template v-if="!parentId">
      <el-form inline @submit.native.prevent><el-form-item><el-input v-model="keyword" clearable placeholder="家长 / 孩子 / 联系电话" @keyup.enter.native="search"/></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button></el-form-item></el-form>
      <el-table v-loading="loading" :data="personalAccounts" @row-click="openPersonal" row-class-name="account-row"><el-table-column label="家长个人账户" min-width="200"><template slot-scope="s"><el-badge :value="s.row.pendingCount" :hidden="!Number(s.row.pendingCount)" :max="99"><strong>{{s.row.parentName}}</strong></el-badge><div class="muted">家长 #{{s.row.parentId}}</div></template></el-table-column><el-table-column prop="parentPhone" label="联系电话" min-width="150"/><el-table-column prop="childCount" label="孩子数量" width="100"/><el-table-column prop="pendingCount" label="待登记课程付款" width="150"/><el-table-column prop="modifiedTime" label="最近课程变更" width="170"/><el-table-column label="操作" width="120"><template><el-button type="text">查看账户 ›</el-button></template></el-table-column></el-table>
    </template>
    <template v-else>
      <el-button type="text" icon="el-icon-back" :disabled="submitting" @click="back">返回家长账户</el-button>
      <el-card v-if="detail" shadow="never" class="summary"><div class="heading"><div><h3>{{detail.parent.parentName}}</h3><span class="muted">{{detail.parent.parentPhone || '未留电话'}} · {{accounts.length}} 位孩子</span></div><el-badge :value="pendingCount" :hidden="!pendingCount" :max="99"><el-button @click="togglePending">待登记课程付款</el-button></el-badge></div></el-card>
      <el-tabs v-model="tab" @tab-click="changeTab"><el-tab-pane label="孩子课包" name="children"/><el-tab-pane name="enrollments"><span slot="label">课程付款 <el-badge :value="pendingCount" :hidden="!pendingCount" :max="99"/></span></el-tab-pane><el-tab-pane label="商城交易" name="orders"/><el-tab-pane label="操作记录" name="history"/></el-tabs>
      <template v-if="tab==='children'">
        <el-alert title="报名和孩子信息共用同一账户。修改资料不覆盖旧报名姓名；有余额、报名或交易历史的孩子不能直接删除。" type="info" :closable="false" class="notice"/>
        <el-table v-loading="loading" :data="accounts"><el-table-column label="孩子" min-width="180"><template slot-scope="s"><strong>{{s.row.studentName}}</strong><div class="muted">{{s.row.gradeName}} · 孩子 #{{s.row.accountId}}</div></template></el-table-column><el-table-column prop="contactPhone" label="联系电话" min-width="130"/><el-table-column label="可用课次" width="110"><template slot-scope="s"><strong class="available">{{s.row.availableCredits}}</strong></template></el-table-column><el-table-column label="剩余 / 暂占 / 已消耗" min-width="170"><template slot-scope="s">{{s.row.remainingCredits}} / {{s.row.reservedCredits}} / {{s.row.consumedCredits}}</template></el-table-column><el-table-column label="操作" min-width="310"><template slot-scope="s"><el-button type="text" @click="openAdjust(s.row,'GRANT')">发放</el-button><el-button type="text" @click="openAdjust(s.row,'WITHDRAW')">收回</el-button><el-button type="text" @click="showCreditHistory(s.row)">课次记录</el-button><el-button type="text" @click="openEdit(s.row)">修改资料</el-button><el-button type="text" @click="removeChild(s.row)">删除</el-button></template></el-table-column></el-table>
      </template>
      <template v-else-if="tab==='enrollments'">
        <el-checkbox v-model="pendingOnly" @change="changeTab">仅看待登记付款</el-checkbox>
        <el-alert v-if="detail && detail.unlinkedCount" :title="`${detail.unlinkedCount}条旧报名待关联孩子，请核对后关联，不按姓名自动合并。`" type="info" :closable="false" class="notice"/>
        <el-table v-loading="loading" :data="records"><el-table-column label="学生 / 孩子归属" min-width="190"><template slot-scope="s"><strong>{{s.row.studentName}}</strong><div class="muted">{{s.row.lessonAccountId ? s.row.childName+' #'+s.row.lessonAccountId : '旧记录 · 孩子待关联'}}</div></template></el-table-column><el-table-column prop="courseClassName" label="课程" min-width="180"/><el-table-column label="日期 / 报名状态" min-width="150"><template slot-scope="s">{{s.row.classDate || '班课'}}<div class="muted">{{statusText(s.row.enrollmentStatus)}}</div></template></el-table-column><el-table-column label="付款" min-width="140"><template slot-scope="s"><el-tag :type="s.row.pending?'warning':'info'">{{s.row.settlementMethod==='P'?'课包结算':payText(s.row.payStatus)}}</el-tag><div class="muted">{{s.row.settlementMethod==='P'?'不计为本次现金收入':(s.row.payableAmount==null?'待核价／历史核验':`应收 ¥${s.row.payableAmount} · 实收 ¥${s.row.receivedAmount} · 已退 ¥${s.row.refundedAmount}`)}}</div></template></el-table-column><el-table-column prop="modifiedTime" label="修改时间" width="165"/><el-table-column label="操作" min-width="300"><template slot-scope="s"><el-button v-if="s.row.settlementMethod!=='P'" type="text" @click="openFinance(s.row)">收费与退款</el-button><el-button v-if="!s.row.lessonAccountId" type="text" @click="openLink(s.row)">核对孩子</el-button></template></el-table-column></el-table>
      </template>
      <template v-else-if="tab==='orders'">
        <el-table v-loading="loading" :data="records"><el-table-column label="商城订单" min-width="220"><template slot-scope="s"><strong>{{s.row.title || '商城订单'}}</strong><div class="muted">{{s.row.orderCode}}</div></template></el-table-column><el-table-column label="订单状态" width="120"><template slot-scope="s">{{orderText(s.row.orderStatus)}}</template></el-table-column><el-table-column label="付款状态" width="120"><template slot-scope="s">{{payText(s.row.payStatus)}}</template></el-table-column><el-table-column label="应付 / 实付 / 已退" min-width="200"><template slot-scope="s">¥{{s.row.payableAmount}} / {{s.row.paidAmount==null?'未付款':'¥'+s.row.paidAmount}} / ¥{{s.row.refundedAmount}}</template></el-table-column><el-table-column prop="modifiedTime" label="修改时间" width="170"/></el-table>
      </template>
      <template v-else>
        <el-table v-loading="loading" :data="records"><el-table-column label="操作" min-width="140"><template slot-scope="s">{{actionText(s.row.action)}}</template></el-table-column><el-table-column prop="title" label="对象" min-width="210"/><el-table-column label="课次 / 付款状态" min-width="180"><template slot-scope="s">{{s.row.quantity==null?'':s.row.quantity+' 次额度'}}<span v-if="s.row.action==='PAYMENT_STATUS'">{{payText(s.row.previousStatus)}} → {{payText(s.row.nextStatus)}}</span></template></el-table-column><el-table-column prop="reason" label="说明" min-width="210"/><el-table-column prop="actorName" label="操作人" width="120"/><el-table-column prop="modifiedTime" label="修改时间" width="170"/></el-table>
      </template>
    </template>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="notice"/>
    <pagination v-if="!parentId || tab!=='children'" v-show="total>0" :total="total" :page.sync="pageNum" :limit="30" :page-sizes="[30]" @pagination="load"/>
    <el-dialog :title="formKind==='adjust'?(form.action==='GRANT'?'发放课次':'收回课次'):(formKind==='edit'?'修改孩子资料':'添加孩子信息')" :visible.sync="formOpen" width="520px" :close-on-click-modal="!submitting" :show-close="!submitting" :before-close="closeForm">
      <el-form label-width="100px" :disabled="submitting"><template v-if="formKind!=='adjust'"><el-form-item v-if="!parentId && formKind==='create'" label="家长账号" required><el-select v-model="form.parentId" filterable remote :remote-method="findParents" placeholder="查找家长姓名或电话" class="wide"><el-option v-for="p in parents" :key="p.userId" :value="p.userId" :label="`${p.userName} · ${p.phonenumber || '无手机号'} · #${p.userId}`"/></el-select></el-form-item><el-form-item label="孩子姓名" required><el-input v-model="form.studentName" maxlength="30"/></el-form-item><el-form-item label="年级" required><el-select v-model="form.gradeName" class="wide"><el-option v-for="g in dict.type.edu_grade" :key="g.value" :value="g.label" :label="g.label"/></el-select></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone" maxlength="11"/></el-form-item></template><template v-else><el-form-item label="孩子">{{selected.studentName}} · 可用 {{selected.availableCredits}} 次</el-form-item><el-form-item label="课次数量" required><el-input-number v-model="form.quantity" :min="1" :max="100000" :precision="0"/></el-form-item><el-form-item label="原因" required><el-input v-model="form.reason" type="textarea" maxlength="255"/></el-form-item></template></el-form><span slot="footer"><el-button :disabled="submitting" @click="formOpen=false">取消</el-button><el-button type="primary" :loading="submitting" @click="save">确认</el-button></span>
    </el-dialog>
    <el-dialog title="核对旧报名孩子归属" :visible.sync="linkOpen" width="520px" :close-on-click-modal="!submitting" :show-close="!submitting"><p>{{linkEnrollment.studentName}} · {{linkEnrollment.courseClassName}}</p><el-select v-model="linkAccountId" class="wide" placeholder="选择已核对的孩子"><el-option v-for="a in accounts" :key="a.accountId" :value="a.accountId" :label="`${a.studentName} · ${a.gradeName} · #${a.accountId}`"/></el-select><el-input v-model="linkReason" type="textarea" maxlength="255" placeholder="核对说明（必填）" class="link-reason"/><span slot="footer"><el-button :disabled="submitting" @click="linkOpen=false">取消</el-button><el-button type="primary" :loading="submitting" @click="saveLink">确认关联</el-button></span></el-dialog>
    <el-dialog :title="historyTitle" :visible.sync="historyOpen" width="760px"><el-table :data="history"><el-table-column prop="label" label="操作" min-width="150"/><el-table-column prop="balance" label="变更后额度" min-width="190"/><el-table-column prop="actorName" label="操作人" width="110"/><el-table-column prop="createTime" label="时间" width="165"/><el-table-column prop="reason" label="原因" min-width="160"/></el-table></el-dialog>
  </div>
</template>
<script>
import * as api from '@/api/system/transaction'
const actions={PAYMENT_PENDING:'收款待确认',PAYMENT_UNKNOWN:'收款待核对',PAYMENT_SUCCESS:'收款成功',PAYMENT_CLOSED:'付款关闭',PAYMENT_FAILED:'收款失败',REFUND_PENDING_REVIEW:'退款待审核',REFUND_APPROVED:'退款已审核',REFUND_PROCESSING:'退款处理中',REFUND_UNKNOWN:'退款待核对',REFUND_SUCCESS:'退款成功',REFUND_CANCELLED:'退款撤回',REFUND_REJECTED:'退款拒绝',REFUND_FAILED:'退款失败',GRANT:'发放课次',WITHDRAW:'收回课次',HOLD:'预约暂占',RELEASE:'释放暂占',CONSUME:'课后消耗',SUBMIT:'提交报名',CONFIRM:'确认报名',REJECT:'拒绝报名',REQUEST_CANCEL:'申请取消',APPROVE_CANCEL:'同意取消',REJECT_CANCEL:'拒绝取消',PAYMENT_STATUS:'付款登记',LINK_CHILD:'核对孩子归属',CREATE:'创建订单',MOCK_PAY:'模拟付款',MOCK_REFUND:'模拟退款',RECEIVE:'确认收货',CANCEL:'取消订单',EXPIRE:'订单超时',SHIP:'发货'}
const requestKey=()=>`child_${Date.now()}_${Math.random().toString(36).slice(2,14)}`
export default {
  name:'EduTransactions',dicts:['edu_grade'],
  data(){return{parentId:null,detail:null,tab:'children',keyword:'',personalAccounts:[],accounts:[],records:[],pendingCount:0,pendingOnly:false,pageNum:1,total:0,loading:false,error:'',formOpen:false,formKind:'',form:{},parents:[],selected:{},submitting:false,historyOpen:false,historyTitle:'',history:[],version:0,parentVersion:0,linkOpen:false,linkEnrollment:{},linkAccountId:null,linkReason:''}},
  created(){this.load()},beforeDestroy(){this.version++;this.parentVersion++},
  methods:{
    payText(v){return({'0':'未支付','1':'已支付','2':'已退款'})[v] || v || '未支付'},statusText(v){return({'0':'待确认','1':'已确认','2':'已取消','3':'已拒绝'})[v] || v},orderText(v){return({WAIT_PAY:'待付款',WAIT_SHIP:'待发货',WAIT_RECEIVE:'待收货',COMPLETED:'已完成',CLOSED:'已关闭',CANCELED:'已取消'})[v] || v},actionText(v){return actions[v] || v},
    search(){this.pageNum=1;this.load()},changeTab(){this.pageNum=1;this.load()},togglePending(){this.tab='enrollments';this.pendingOnly=!this.pendingOnly;this.changeTab()},
    openPersonal(row){if(this.submitting)return;this.parentId=row.parentId;this.detail=null;this.accounts=[];this.records=[];this.tab='children';this.pageNum=1;this.pendingOnly=false;this.load()},back(){this.parentId=null;this.detail=null;this.records=[];this.pageNum=1;this.load()},
    async load(){const v=++this.version;this.loading=true;this.error='';try{if(!this.parentId){const r=await api.listPersonalAccounts({keyword:this.keyword,pageNum:this.pageNum});if(v===this.version){this.personalAccounts=r.data.rows || [];this.total=r.data.total;this.pendingCount=Number(r.data.pendingCount)}}else{const [a,b]=await Promise.all([api.personalDetail(this.parentId),this.tab==='children'?Promise.resolve({data:{rows:[],total:0}}):api.personalRecords(this.parentId,{kind:this.tab,pageNum:this.pageNum,pendingOnly:this.tab==='enrollments' && this.pendingOnly})]);if(v===this.version){this.detail=a.data;this.accounts=a.data.children || [];this.pendingCount=Number(a.data.pendingCount);this.records=b.data.rows || [];this.total=b.data.total}}}catch(e){if(v===this.version){this.error='账户数据加载失败，请重新查询';this.personalAccounts=[];this.accounts=[];this.records=[];this.detail=null;this.pendingCount=0}}finally{if(v===this.version)this.loading=false}},
    openCreate(){this.formKind='create';this.form={parentId:this.parentId,studentName:'',gradeName:'',contactPhone:(this.detail && this.detail.parent.parentPhone) || '',requestKey:requestKey()};this.formOpen=true;if(!this.parentId)this.findParents('')},
    openEdit(row){this.selected=row;this.formKind='edit';this.form={studentName:row.studentName,gradeName:row.gradeName,contactPhone:row.contactPhone || ''};this.formOpen=true},
    async findParents(keyword){const v=++this.parentVersion;try{const r=await api.listParents({keyword});if(v===this.parentVersion)this.parents=r.data || []}catch(e){this.$modal.msgError('家长查询失败')}},
    openAdjust(row,action){this.selected=row;this.formKind='adjust';this.form={action,quantity:1,reason:'',requestKey:requestKey()};this.formOpen=true},closeForm(done){if(!this.submitting)done()},
    async save(){if(this.submitting)return;const f=this.form,kind=this.formKind;if(kind!=='adjust' && (!f.studentName.trim() || !f.gradeName || (kind==='create' && !f.parentId))){this.$modal.msgError('请填写孩子、年级并选择家长');return}if(kind==='adjust' && (!Number.isInteger(f.quantity) || f.quantity<1 || !f.reason.trim())){this.$modal.msgError('请输入正整数课次和操作原因');return}this.submitting=true;try{if(kind==='create')await api.createAccount({...f,studentName:f.studentName.trim()});else if(kind==='edit')await api.editChild(this.selected.accountId,f);else await api.adjustCredits(this.selected.accountId,{...f,reason:f.reason.trim()});this.formOpen=false;this.$modal.msgSuccess('操作完成');await this.load()}finally{this.submitting=false}},
    async removeChild(row){try{await this.$confirm(`确认删除${row.studentName}？有余额、报名或交易历史的孩子不能删除。`,'删除孩子资料');await api.deleteChild(row.accountId);this.$modal.msgSuccess('删除成功');await this.load()}catch(e){if(e!=='cancel' && e!=='close')this.$modal.msgError(e.message || '删除失败')}},
    async showCreditHistory(row){const r=await api.creditHistory(row.accountId);this.historyTitle=`${row.studentName} · 最近200条课次记录（完整历史见操作记录）`;this.history=(r.data || []).map(e=>({...e,label:`${actions[e.action] || e.action} ${e.quantity}次`,balance:`剩余${e.remainingAfter} / 暂占${e.reservedAfter} / 消耗${e.consumedAfter}`}));this.historyOpen=true},
    openFinance(row){this.$router.push({path:'/finance/tuition',query:{enrollmentId:String(row.enrollmentId)}})},
    openLink(row){this.linkEnrollment=row;this.linkAccountId=null;this.linkReason='';this.linkOpen=true},
    async saveLink(){if(this.submitting)return;if(!this.linkAccountId || !this.linkReason.trim()){this.$modal.msgError('请选择孩子并填写核对说明');return}this.submitting=true;try{await api.linkChild(this.linkEnrollment.enrollmentId,{accountId:this.linkAccountId,reason:this.linkReason.trim()});this.linkOpen=false;await this.load()}finally{this.submitting=false}}
  }
}
</script>
<style scoped>
.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.heading h2{margin:0 16px 8px 0;font-size:24px;color:#253047}.heading p{margin:0;color:#7b8798;font-size:14px}.heading h3{margin:0 0 8px}.notice{margin:16px 0}.muted{font-size:12px;color:#8491a3;margin-top:6px}.available{font-size:23px;color:#2459d9}.wide{width:100%}.summary{margin:12px 0 24px}.summary .heading{margin:0}.link-reason{margin-top:20px}.transaction-page >>> .account-row{cursor:pointer}
</style>
